const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-49.053062, -1.593993]);
  const region = point.buffer(100000); // 100 km radius

  const date = '2009-08-19';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition - MODIS Terra (MOD09GA) for cloud information
  let modisCol = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  // Check if collection is empty
  let colSize = modisCol.size().getInfo();
  console.log(`MODIS Terra images: ${colSize}`);

  if (colSize === 0) {
    // Try MODIS Aqua as fallback
    modisCol = ee.ImageCollection('MODIS/006/MYD09GA')
      .filterDate(startDate, endDate)
      .filterBounds(region);
    colSize = modisCol.size().getInfo();
    console.log(`MODIS Aqua images: ${colSize}`);
  }

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the image
  const image = modisCol.first();

  // 3. Extract cloud mask from 'state_1km' band (bits 0-1: 00=not determined, 01=clear, 10=cloudy)
  const cloudMask = image.select('state_1km')
    .bitwiseAnd(3)  // Get bits 0-1
    .eq(2);         // 2 (binary 10) = cloudy

  // 4. Water mask from JRC Global Surface Water (1984-2020)
  const waterMask = ee.Image('JRC/GSW1_0/GlobalSurfaceWater')
    .select('occurrence')
    .gt(90);  // Permanent water (occurrence > 90%)

  // Land mask is inverse of water mask
  const landMask = waterMask.not();

  // 5. Calculate cloud fractions
  // Cloudy pixels over land
  const cloudLand = cloudMask.updateMask(landMask);
  const landStats = cloudLand.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  });

  // Cloudy pixels over water
  const cloudWater = cloudMask.updateMask(waterMask);
  const waterStats = cloudWater.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  });

  // Get values
  const landSum = landStats.get('state_1km').getInfo();
  const landCount = landStats.get('state_1km_count').getInfo();
  const waterSum = waterStats.get('state_1km').getInfo();
  const waterCount = waterStats.get('state_1km_count').getInfo();

  console.log(`Land: ${landCount} pixels, ${landSum} cloudy`);
  console.log(`Water: ${waterCount} pixels, ${waterSum} cloudy`);

  // 6. Check for valid pixels
  if (landCount === 0 || waterCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate cloud fractions
  const landCloudFraction = landSum / landCount;
  const waterCloudFraction = waterSum / waterCount;

  console.log(`Land cloud fraction: ${landCloudFraction.toFixed(3)}`);
  console.log(`Water cloud fraction: ${waterCloudFraction.toFixed(3)}`);

  // 7. Validate and determine answer
  if (landCloudFraction === null || waterCloudFraction === null ||
      isNaN(landCloudFraction) || isNaN(waterCloudFraction)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if land cloud fraction > water cloud fraction
  if (landCloudFraction > waterCloudFraction) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
